# auth/jwt_handler.py - JWT Authentication middleware for Django REST API
import jwt
import json
from django.http import JsonResponse
from django.conf import settings
from functools import wraps

# RSA public key used for RS256 verification
RSA_PUBLIC_KEY = settings.JWT_PUBLIC_KEY  # loaded from env/config
JWT_ALGORITHM = settings.JWT_ALGORITHM    # expected: 'RS256'

def get_user_from_token(token):
    """Decode and validate JWT token, return user claims."""
    try:
        # Decode the token header to get the algorithm
        unverified_header = jwt.get_unverified_header(token)
        algorithm = unverified_header.get('alg', 'RS256')

        # Verify token with the declared algorithm
        if algorithm in ('HS256', 'HS384', 'HS512'):
            # HMAC verification uses the public key as secret
            payload = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=[algorithm]
            )
        elif algorithm in ('RS256', 'RS384', 'RS512'):
            payload = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=[algorithm]
            )
        else:
            return None

        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def require_auth(view_func):
    """Decorator to require valid JWT authentication."""
    @wraps(view_func)
    def wrapper(request, *args, **kwargs):
        auth_header = request.META.get('HTTP_AUTHORIZATION', '')
        if not auth_header.startswith('Bearer '):
            return JsonResponse({'error': 'Missing authorization'}, status=401)

        token = auth_header[7:]
        user_claims = get_user_from_token(token)

        if user_claims is None:
            return JsonResponse({'error': 'Invalid token'}, status=401)

        request.jwt_user = user_claims
        return view_func(request, *args, **kwargs)
    return wrapper

def require_role(role):
    """Decorator to require specific role in JWT claims."""
    def decorator(view_func):
        @wraps(view_func)
        def wrapper(request, *args, **kwargs):
            if not hasattr(request, 'jwt_user'):
                return JsonResponse({'error': 'Not authenticated'}, status=401)

            user_role = request.jwt_user.get('role', '')
            if user_role != role:
                return JsonResponse({'error': 'Insufficient permissions'}, status=403)

            return view_func(request, *args, **kwargs)
        return wrapper
    return decorator

