from django.db import connection

@require_auth
@require_role('admin')
def admin_promote_user(request):
    """Admin endpoint to promote a user to admin role."""
    data = json.loads(request.body)
    user_id = data.get('user_id')
    new_role = data.get('role', 'admin')

    with connection.cursor() as cursor:
        cursor.execute(
            "UPDATE users SET role = %s WHERE id = %s",
            [new_role, user_id]
        )

    return JsonResponse({'status': 'updated', 'user_id': user_id, 'role': new_role})

@require_auth
def get_user_profile(request):
    """Get current user's profile from database."""
    user_id = request.jwt_user.get('sub')

    with connection.cursor() as cursor:
        cursor.execute(
            "SELECT id, username, email, role FROM users WHERE id = %s",
            [user_id]
        )
        row = cursor.fetchone()

    if row:
        return JsonResponse({
            'id': row[0], 'username': row[1],
            'email': row[2], 'role': row[3]
        })
    return JsonResponse({'error': 'User not found'}, status=404)

@require_auth
def list_users(request):
    """List all users (any authenticated user can view)."""
    with connection.cursor() as cursor:
        cursor.execute("SELECT id, username, role FROM users")
        rows = cursor.fetchall()

    users = [{'id': r[0], 'username': r[1], 'role': r[2]} for r in rows]
    return JsonResponse({'users': users})
